// @openfactory/api-client: typed client of /api/v1, used by the CLI and the dashboard.
// schema.d.ts is generated by `npm run gen:api` from api/openapi.json. Do not edit it.
import createClient, { type ClientOptions } from "openapi-fetch";
import type { paths } from "./schema";

export type { components, operations, paths } from "./schema";
export * from "./errors";
export * from "./transport";
export * from "./sse";
export * from "./pagination";
export * from "./client";

/** Creates a bare openapi-fetch client. baseUrl is the control plane origin plus "/api/v1". */
export function createApiClient(options: ClientOptions = {}) {
  return createClient<paths>(options);
}

export type ApiClient = ReturnType<typeof createApiClient>;
